import {createHash} from 'node:crypto';
import {mockPosts} from './nextjs-posts.mjs';
const region=(id,name)=>({id,name,state:'VIC',center:[145,-38],zoom:10,bbox:[144,-39,146,-37],rasters:[],tiles:{},status:'contours',contour_file:'data/'+id+'-contours.json',contours:{count:2,datum:'AHD'},contour_survey:'Example survey 2020',contour_catalog:'https://example.invalid/contours',notes:'Published reference contours for this test area.',attribution:'Example survey publisher',licence:'CC BY 4.0',map_attribution:'Example survey publisher'});
export const atlasCatalog={format_version:1,updated_at:'2026-11-03',regions:[region('example-bay','Example Bay'),region('second-bay','Second Bay')]};
export const atlasBeaches={revision:'1',states:[{id:'NSW',name:'NSW'},{id:'VIC',name:'VIC'}],areas:[{id:'example-area',name:'Example Area',state_id:'VIC',center:[145,-38],map_region:'example-bay',depth_count:2}],beaches:[{id:'bondi',name:'Bondi Beach',state:'NSW',state_id:'NSW',area_id:'example-area',area_name:'Example Area',point:[145,-38],region:'example-bay',waterbody:'ocean',access_mode:'shore',activities:['freediving']},{id:'portsea',name:'Portsea Beach',state:'VIC',state_id:'VIC',area_id:'example-area',area_name:'Example Area',point:[145.01,-38],region:'example-bay',waterbody:'ocean',access_mode:'shore',activities:['freediving']}],sources:[],location_note:'Reference locations supplied by the example publisher.'};
export const atlasContours={type:'FeatureCollection',features:[10,20].map(depth=>({type:'Feature',properties:{depth_m:depth,datum_label:'AHD',survey_date:'2020'},geometry:{type:'LineString',coordinates:[[144.9,-38.01-depth/10000],[145.1,-38.01-depth/10000]]}}))};
const files=Object.fromEntries([['beaches.json',atlasBeaches],['data/catalog.json',atlasCatalog],['data/example-bay-contours.json',atlasContours],['data/second-bay-contours.json',atlasContours]].map(([path,data])=>{const body=JSON.stringify(data);return [path,{hash:createHash('sha256').update(body).digest('hex'),bytes:Buffer.byteLength(body),label:path}];}));
const manifest={version:1,revision:'fixture',files,regions:Object.fromEntries(atlasCatalog.regions.map(r=>[r.id,{name:r.name,files:['beaches.json','data/catalog.json',r.contour_file],bytes:['beaches.json','data/catalog.json',r.contour_file].reduce((n,path)=>n+files[path].bytes,0)}]))};
export async function mockAtlas(page,base){await mockPosts(page,base);await page.route('**/*',async route=>{const url=new URL(route.request().url());if(!['localhost','127.0.0.1'].includes(url.hostname))return route.abort();return route.fallback();});await page.route('**/v1/sites/catalog*',r=>r.fulfill({json:atlasBeaches}));for(const [path,data]of [['beaches.json',atlasBeaches],['sites-snapshot.json',atlasBeaches],['data/catalog.json',atlasCatalog],['data/downloads.json',manifest],['data/beach-summaries.json',{beaches:[]}],['guides.json',{}],['social.json',{posts:[]}]])await page.route('**/'+path+'*',r=>r.fulfill({json:data}));await page.route(/\/data\/(?:example|second)-bay-contours\.json/,r=>page.evaluate(()=>window.failAtlasContours).then(fail=>fail?r.fulfill({status:503,json:{error:'Synthetic contour request failed'}}):r.fulfill({json:atlasContours})))}
export const seedActivity=async page=>page.evaluate(async()=>{const {applicationBackbone}=await import('/app-backbone.js'),application=await applicationBackbone();if(application?.storage){const stats=await application.storage.stats();await application.storage.evict(stats.entries.map(r=>r.id));}const {activity}=await import('/activity.js');activity.clearFinished();const loaded=activity.begin({label:'Public survey catalogue',kind:'Beach data',url:location.origin+'/data/example.json'});loaded.finish({bytes:4096});activity.resource({name:location.origin+'/data/example.json',startTime:10000,responseEnd:10000,transferSize:2048,decodedBodySize:4096});activity.begin({label:'Shore tiles',kind:'Shore tiles',url:location.origin+'/tiles/one.png'}).finish({state:'error',error:'Image unavailable'});activity.begin({label:'Superseded region',kind:'Survey data'}).finish({state:'cancelled'});window.pendingAtlasActivity=activity.begin({label:'Numeric depth cells',kind:'Survey data'});activity.frame(12.5);activity.queue(3);});
